precision highp float;
uniform highp mat4 cc_matView;
  uniform highp mat4 cc_matProj;
  uniform highp vec4 cc_cameraPos;
uniform highp mat4 cc_matWorld;
  uniform highp mat4 cc_matWorldIT;
attribute vec3 a_position;
attribute vec3 a_normal;
attribute vec2 a_texCoord;
varying vec2 v_uv;
varying vec3 v_worldNormal;
varying vec3 v_worldPos;
varying vec2 v_matcapUV;
varying float v_rimBasic;
vec4 vert() {
  vec4 worldPos4   = cc_matWorld * vec4(a_position, 1.0);
  v_worldPos       = worldPos4.xyz;
  v_worldNormal    = normalize((cc_matWorldIT * vec4(a_normal, 0.0)).xyz);
  v_uv             = a_texCoord;
  vec3 worldN      = v_worldNormal;
  vec3 viewNormal  = normalize((cc_matView * vec4(worldN, 0.0)).xyz);
  v_matcapUV       = viewNormal.xy * 0.5 + 0.5;
  vec3 viewDir     = normalize(cc_cameraPos.xyz - worldPos4.xyz);
  float NdotV      = max(dot(v_worldNormal, viewDir), 0.0);
  v_rimBasic       = 1.0 - NdotV;
  return cc_matProj * cc_matView * worldPos4;
}
void main() { gl_Position = vert(); }

